#!/usr/bin/env python3
# ============================================================================
# dag_assert.py 鈥?DAG assertion (spec 搂3.3 transition 2, PLANNED->DISPATCHABLE)
# Purpose : Assert dag.json is acyclic AND intra-wave authorized_paths are
#           pairwise non-intersecting (write-parallel physical isolation).
# Input   : data/packets/dag.json {"edges":[[a,b],...],"waves":[[pid,...],...]}
#           + data/packets/<pid>.json (4-field packets with authorized_paths).
# Output  : exit 0 = pass, 1 = fail (reasons on stderr). Zero-token, no LLM.
# Lines   : ~30 (excluding this header)
# ============================================================================
import json, os, sys
ROOT = os.environ.get("LOOP_ROOT", os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
PK = os.path.join(ROOT, "data", "packets")

def fail(msg):
    sys.stderr.write("DAG_ASSERT FAIL: %s\n" % msg); sys.exit(1)

dag = json.load(open(sys.argv[1] if len(sys.argv) > 1 else os.path.join(PK, "dag.json")))
edges, waves = dag.get("edges", []), dag.get("waves", [])
nodes = {n for e in edges for n in e} | {p for w in waves for p in w}
# Kahn's algorithm: acyclic iff all nodes can be topologically removed.
indeg = {n: 0 for n in nodes}
for a, b in edges:
    indeg[b] += 1
queue, seen = [n for n in nodes if indeg[n] == 0], 0
while queue:
    n = queue.pop(); seen += 1
    for a, b in edges:
        if a == n:
            indeg[b] -= 1
            if indeg[b] == 0:
                queue.append(b)
if seen != len(nodes):
    fail("cycle detected (%d/%d nodes sorted)" % (seen, len(nodes)))
norm = lambda p: p.rstrip("/") + "/"
for w, wave in enumerate(waves):
    paths = {pid: json.load(open(os.path.join(PK, pid + ".json")))["authorized_paths"] for pid in wave}
    for i, a in enumerate(wave):
        for b in wave[i + 1:]:
            for pa in paths[a]:
                for pb in paths[b]:
                    if norm(pa).startswith(norm(pb)) or norm(pb).startswith(norm(pa)):
                        fail("wave %d: %s and %s intersect on %r vs %r" % (w, a, b, pa, pb))
print("DAG_ASSERT PASS: %d nodes acyclic, %d waves path-disjoint" % (len(nodes), len(waves)))

#!/usr/bin/env python3
"""Recover one imported parent manifest from a historical-event replay."""
from __future__ import annotations

import argparse
import contextlib
import json
import os
import time
from pathlib import Path

from orchestration_common import LoopPaths, atomic_write_json, file_lock, read_json


@contextlib.contextmanager
def retry_lock(path: Path, timeout: float = 30.0):
    deadline = time.monotonic() + timeout
    while True:
        manager = file_lock(path)
        try:
            manager.__enter__()
            break
        except OSError:
            if time.monotonic() >= deadline:
                raise
            time.sleep(0.1)
    try:
        yield
    finally:
        manager.__exit__(None, None, None)


def valid_report(path: Path, packet_id: str) -> bool:
    value = read_json(path, None)
    return isinstance(value, dict) and value.get("packet_id") == packet_id


def recover(root: Path, manifest_id: str) -> dict[str, object]:
    paths = LoopPaths.resolve(root)
    stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime())
    evidence = paths.data / "repairs" / ("parent-replay-incident-" + stamp)
    evidence.mkdir(parents=True, exist_ok=False)
    quarantine = evidence / "quarantine"
    (quarantine / "dead_letters").mkdir(parents=True)
    (quarantine / "sol_wake").mkdir(parents=True)
    selected: list[str] = []
    states: dict[str, str] = {}
    # The outer lock excludes already-scheduled full epilogues.  The events
    # lock makes cursor=EOF a true cut: later terminal edges append after it.
    with retry_lock(paths.data / "orchestration" / ".epilogue.lock"):
        with retry_lock(paths.events_lock):
            with retry_lock(paths.data / "progress_ledger.lock"):
                before = paths.ledger.read_bytes()
                ledger = json.loads(before.decode("utf-8"))
                roster = read_json(paths.data / "lifecycle" / "exec_roster.json",
                                   {"jobs": {}}) or {"jobs": {}}
                jobs = roster.get("jobs") if isinstance(roster, dict) else {}
                jobs = jobs if isinstance(jobs, dict) else {}
                event_cursor = paths.events.stat().st_size if paths.events.exists() else 0
                for packet_id, entry in (ledger.get("packets") or {}).items():
                    if entry.get("manifest_id") != manifest_id:
                        continue
                    selected.append(packet_id)
                    entry.setdefault("history", [])
                    entry.setdefault("attempts", 0)
                    job = jobs.get(packet_id) if isinstance(jobs.get(packet_id), dict) else {}
                    run_id = job.get("run_id")
                    job_state = str(job.get("state") or "")
                    report = paths.data / "reports" / packet_id / "report.json"
                    if job_state in {"starting", "running"} and run_id:
                        state = "RUNNING"
                    elif job_state == "completed" and valid_report(report, packet_id):
                        state = "REPORTED"
                    elif job_state in {"spawn_failed"}:
                        state = "DISPATCHABLE"
                    else:
                        state = "FAILED"
                    entry["state"] = state
                    if run_id:
                        entry["current_run_id"] = str(run_id)
